def transform(grid):
 h=len(grid); w=len(grid[0]); out=[[0]*w for _ in range(h)]
 # identify the enclosing red frame
 pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
 r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
 seen=set()
 for r in range(r0+1,r1):
  for c in range(c0+1,c1):
   col=grid[r][c]
   if col==0 or (r,c) in seen: continue
   stack=[(r,c)]; seen.add((r,c)); component=[]
   while stack:
    y,x=stack.pop(); component.append((y,x))
    for yy,xx in [(y-1,x),(y+1,x),(y,x-1),(y,x+1)]:
     if r0<yy<r1 and c0<xx<c1 and (yy,xx) not in seen and grid[yy][xx]==col:
      seen.add((yy,xx)); stack.append((yy,xx))
   a=min(y for y,x in component)-r0-1; b=min(x for y,x in component)-c0-1
   dh=max(y for y,x in component)-min(y for y,x in component)+1
   dw=max(x for y,x in component)-min(x for y,x in component)+1
   for y in range(4*a,4*(a+dh)):
    for x in range(4*b,4*(b+dw)):
     if y>=h or x>=w: continue
     if y in (4*a,4*(a+dh)-1) or x in (4*b,4*(b+dw)-1): out[y][x]=col
     elif y<=4*a+2*dh-1 and x<=4*b+2*dw-1: out[y][x]=2
 return out

